NEW_BACKEND = Path("wa_backend/api/simple_products.py")
NEW_PAGE = Path("dashboard/src/pages/ProductsDashboard.tsx")
NEW_GATE = Path("wa_backend/scripts/gate_stage7_simple_products.py")

def run(*args: str) -> str:
    proc = subprocess.run(args, text=True, encoding='utf-8', errors='replace', capture_output=True)
    if proc.returncode != 0:
        raise SystemExit('ERROR running: ' + ' '.join(args) + '\n' + proc.stderr)
    return proc.stdout.strip()

def read_normalized(path: Path) -> tuple[str, bool]:
    raw = path.read_bytes()
    uses_crlf = b'\r\n' in raw
    text = raw.replace(b'\r\n', b'\n').replace(b'\r', b'\n').decode('utf-8')
    return text, uses_crlf

def encode_text(text: str, uses_crlf: bool) -> bytes:
    raw = text.encode('utf-8')
    return raw.replace(b'\n', b'\r\n') if uses_crlf else raw

def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'ERROR: expected exactly one {label}, found {count}. No files were modified.')
    return text.replace(old, new, 1)

def main() -> None:
    head = run('git', 'rev-parse', 'HEAD')
    if head != EXPECTED_HEAD:
        raise SystemExit(f'ERROR: expected stage 7 HEAD {EXPECTED_HEAD}, got {head}. No files were modified.')

    touched = sorted({Path(row[0]) for row in REPLACEMENTS}, key=str)
    for path in touched:
        if not path.is_file():
            raise SystemExit(f'ERROR: missing {path}. No files were modified.')
        if subprocess.run(['git', 'diff', '--quiet', '--', str(path)]).returncode != 0:
            raise SystemExit(f'ERROR: {path} has unstaged changes. No files were modified.')
        if subprocess.run(['git', 'diff', '--cached', '--quiet', '--', str(path)]).returncode != 0:
            raise SystemExit(f'ERROR: {path} has staged changes. No files were modified.')

    for path in (NEW_BACKEND, NEW_PAGE, NEW_GATE):
        if path.exists():
            raise SystemExit(f'ERROR: {path} already exists. No files were modified.')

    states: dict[Path, tuple[str, bool]] = {}
    for path in touched:
        states[path] = read_normalized(path)

    for raw_path, old, new, label in REPLACEMENTS:
        path = Path(raw_path)
        text, crlf = states[path]
        states[path] = (replace_once(text, old, new, label), crlf)

    # Compile every Python source before the first write.
    for path, (text, _crlf) in states.items():
        if path.suffix == '.py':
            compile(text, str(path), 'exec')
    compile(BACKEND_TEXT, str(NEW_BACKEND), 'exec')
    compile(GATE_TEXT, str(NEW_GATE), 'exec')

    sidebar = states[Path('dashboard/src/components/operations/OperationsSidebar.tsx')][0]
    app = states[Path('dashboard/src/App.tsx')][0]
    inventory = states[Path('dashboard/src/pages/inventory/MainInventory.tsx')][0]
    if 'label: "التسعير التجاري"' in sidebar or 'path: "/pricing"' in sidebar:
        raise RuntimeError('Advanced pricing is still visible in the sidebar.')
    if '<Route path="/pricing" element={<Navigate to="/products" replace />} />' not in app:
        raise RuntimeError('Legacy pricing route was not frozen.')
    if 'id: "catalog"' in inventory or 'TabProductCatalog' in inventory:
        raise RuntimeError('Technical catalog is still visible in Inventory.')
    for marker in ('حفظ المنتج والسعر', 'استيراد CSV', 'سعر الحبة المحسوب'):
        if marker not in PAGE_TEXT:
            raise RuntimeError(f'Missing Products UI marker: {marker}')
    for marker in ('create_publication(', 'create_draft_entry(', 'publish_publication(', 'packs_per_carton=int(item.units_per_carton)'):
        if marker not in BACKEND_TEXT:
            raise RuntimeError(f'Missing backend invariant: {marker}')

    writes: list[tuple[Path, bytes]] = []
    for path, (text, crlf) in states.items():
        writes.append((path, encode_text(text, crlf)))
    writes.extend([
        (NEW_BACKEND, BACKEND_TEXT.encode('utf-8')),
        (NEW_PAGE, PAGE_TEXT.encode('utf-8')),
        (NEW_GATE, GATE_TEXT.encode('utf-8')),
    ])

    temps: list[tuple[Path, Path]] = []
    try:
        for path, payload in writes:
            tmp = path.with_suffix(path.suffix + '.stage7_simple_products.tmp')
            tmp.parent.mkdir(parents=True, exist_ok=True)
            tmp.write_bytes(payload)
            temps.append((tmp, path))
        for tmp, path in temps:
            tmp.replace(path)
    finally:
        for tmp, _path in temps:
            if tmp.exists():
                tmp.unlink()

    print('STAGE7_SIMPLE_PRODUCTS_APPLIED_OK')
    print('Visible dashboard: Products only; advanced pricing is hidden and /pricing redirects to /products')
    print('Manual workflow: name + units/carton + carton price -> one save')
    print('Bulk workflow: one CSV row per product, up to 200 rows, atomic import')
    print('Internal authority preserved: Product/Variant/UOM + temporal PriceBook history')

if __name__ == '__main__':
    main()
